using System;using System.IO;using System.Linq;using System.Collections.Generic;using HdrPilot;
class EffectTests{static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Core.Data=Path.Combine(root,"data");Core.Init();var g=new Game{Id="effects",Name="Fixture",Root=root,Exe=Path.Combine(root,"Game.exe")};File.Copy(typeof(Core).Assembly.Location,g.Exe);foreach(var effect in EffectCatalog.All){string name=effect.Addon?"AutoHDR.addon64":"reshade-shaders/HDRUnlock-"+effect.Id+"/Shaders/test.fx";string file=Path.Combine(root,name);Directory.CreateDirectory(Path.GetDirectoryName(file));if(effect.Addon)File.Copy(g.Exe,file);else File.WriteAllText(file,"fixture");File.WriteAllText(Path.Combine(root,"hdr-unlock-effects-"+effect.Id+".json"),Core.Json.Serialize(new DlssManifest{Game=g.Id,Folder=root,Files=new List<DlssFile>{new DlssFile{Name=name,After=DlssCore.Hash(file)}}}));}foreach(var effect in EffectCatalog.All){var before=ModInventory.Scan(g).Where(i=>i.Id=="effect").ToList();var item=before.Single(i=>i.Effect.Id==effect.Id);string recovery=DlssCore.Apply(g,ModInventory.Remove(item));if(ModInventory.Scan(g).Any(i=>i.Id=="effect"&&i.Effect.Id==effect.Id)||ModInventory.Scan(g).Count(i=>i.Id=="effect")!=before.Count-1)throw new Exception("Removal failed "+effect.Id);DlssCore.Apply(g,DlssCore.Recovery(g,Path.Combine(recovery,"transaction.json")));if(ModInventory.Scan(g).Count(i=>i.Id=="effect")!=before.Count)throw new Exception("Recovery failed "+effect.Id);Console.WriteLine("PASS independent deletion + recovery: "+effect.Id);}return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}}
